SELECT pi.material_id AS "materialId", SUM(pi.material_qty) AS "qty" FROM ecom_package_item pi JOIN ecom_package p ON p.id = pi.package_id WHERE p.warehouse_id = #{warehouseId} AND p.status IN ('WAIT_LABEL', 'LABELED') AND pi.material_id IN #{m}
AND p.id NOT IN #{x}
GROUP BY pi.material_id
